=== FILE: tb/tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// The reference model is written from interface_spec.md (MAC-RESET, MAC-CLEAR,
// MAC-ACC, MAC-HOLD, MAC-SAT, MAC-STICKY), not from the RTL.
// Inputs are driven at the falling edge. Outputs are compared before each
// rising edge (must be unchanged) and after it (must match the model).
`timescale 1ns / 1ps
module tb_mac8;
    localparam integer MAX_ACC     = 16777215;   // 0xFFFFFF
    localparam integer MAX_REPORTS = 20;
    localparam integer RAND_EDGES  = 6000;

    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        clr   = 1'b0;
    reg        en    = 1'b0;
    reg  [7:0] a     = 8'd0;
    reg  [7:0] b     = 8'd0;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk(clk), .rst_n(rst_n), .clr(clr), .en(en),
        .a(a), .b(b), .acc(acc), .sat(sat)
    );

    always #5 clk = ~clk;

    // Reference model state.
    integer m_acc;
    reg     m_sat;
    reg     m_valid;

    // Scoreboard counters.
    integer n_pass;
    integer n_fail;
    integer n_reports;
    integer cycle;

    // Corner counters.
    integer n_sat_set;
    integer n_sticky;
    integer n_exact_max;
    integer n_clr_with_en;
    integer n_clr_when_sat;
    integer n_rst_with_en;
    integer n_rst_when_sat;
    integer n_hold;

    // Verdict support.
    reg [8*128-1:0] nonce;
    reg [7:0]       ch;
    integer         i;
    reg             verdict_done;

    // Random stimulus.
    reg [31:0] rs;
    reg [31:0] ctl;
    reg [31:0] opd;
    reg        r_rst, r_clr, r_en;
    reg [7:0]  ra, rb;
    integer    k;

    // Reference model: one rising edge, from the specification.
    task model_edge;
        input       r;
        input       c;
        input       e;
        input [7:0] x;
        input [7:0] y;
        integer p;
        integer t;
        begin
            p = x * y;
            if (!r) begin
                // MAC-RESET
                if (e) n_rst_with_en = n_rst_with_en + 1;
                if (m_valid && m_sat) n_rst_when_sat = n_rst_when_sat + 1;
                m_acc   = 0;
                m_sat   = 1'b0;
                m_valid = 1'b1;
            end else if (m_valid) begin
                if (c) begin
                    // MAC-CLEAR: clear wins over an accumulate.
                    if (e) n_clr_with_en = n_clr_with_en + 1;
                    if (m_sat) n_clr_when_sat = n_clr_when_sat + 1;
                    m_acc = 0;
                    m_sat = 1'b0;
                end else if (e) begin
                    // MAC-ACC, MAC-SAT, MAC-STICKY
                    t = m_acc + p;
                    if (t > MAX_ACC) begin
                        if (m_sat) n_sticky = n_sticky + 1;
                        else       n_sat_set = n_sat_set + 1;
                        m_acc = MAX_ACC;
                        m_sat = 1'b1;
                    end else begin
                        if (t == MAX_ACC && m_acc < MAX_ACC && !m_sat)
                            n_exact_max = n_exact_max + 1;
                        if (m_sat) n_sticky = n_sticky + 1;
                        m_acc = t;
                    end
                end else begin
                    // MAC-HOLD
                    n_hold = n_hold + 1;
                    if (m_sat) n_sticky = n_sticky + 1;
                end
            end
        end
    endtask

    // Compare both outputs with the model; every compare counts.
    task compare_outputs;
        input post_edge;
        reg [23:0] exp_acc;
        begin
            exp_acc = m_acc[23:0];
            if (acc === exp_acc) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                if (n_reports < MAX_REPORTS) begin
                    n_reports = n_reports + 1;
                    if (post_edge)
                        $display("MISMATCH acc after edge %0d: rst_n=%b clr=%b en=%b a=%h b=%h expected %h got %h",
                                 cycle, rst_n, clr, en, a, b, exp_acc, acc);
                    else
                        $display("MISMATCH acc before edge %0d (changed without a rising edge): rst_n=%b clr=%b en=%b a=%h b=%h expected %h got %h",
                                 cycle, rst_n, clr, en, a, b, exp_acc, acc);
                end
            end
            if (sat === m_sat) begin
                n_pass = n_pass + 1;
            end else begin
                n_fail = n_fail + 1;
                if (n_reports < MAX_REPORTS) begin
                    n_reports = n_reports + 1;
                    if (post_edge)
                        $display("MISMATCH sat after edge %0d: rst_n=%b clr=%b en=%b a=%h b=%h acc=%h expected %b got %b",
                                 cycle, rst_n, clr, en, a, b, acc, m_sat, sat);
                    else
                        $display("MISMATCH sat before edge %0d (changed without a rising edge): rst_n=%b clr=%b en=%b a=%h b=%h expected %b got %b",
                                 cycle, rst_n, clr, en, a, b, m_sat, sat);
                end
            end
        end
    endtask

    // Drive one set of inputs, then check across one rising edge.
    task drive_edge;
        input       r;
        input       c;
        input       e;
        input [7:0] x;
        input [7:0] y;
        begin
            @(negedge clk);
            rst_n = r; clr = c; en = e; a = x; b = y;
            #1;
            if (m_valid) compare_outputs(1'b0);
            @(posedge clk);
            model_edge(r, c, e, x, y);
            #1;
            if (m_valid) compare_outputs(1'b1);
            cycle = cycle + 1;
        end
    endtask

    task rnd_next;
        begin
            rs = rs ^ (rs << 13);
            rs = rs ^ (rs >> 17);
            rs = rs ^ (rs << 5);
        end
    endtask

    task print_verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $write("NIRMAAN-SIM ");
                for (i = 127; i >= 0; i = i - 1) begin
                    ch = nonce[i*8 +: 8];
                    if (ch != 8'd0) $write("%c", ch);
                end
                $display(" %0d passed, %0d failed", n_pass, n_fail);
            end
        end
    endtask

    initial begin
        m_acc = 0; m_sat = 1'b0; m_valid = 1'b0;
        n_pass = 0; n_fail = 0; n_reports = 0; cycle = 0;
        n_sat_set = 0; n_sticky = 0; n_exact_max = 0;
        n_clr_with_en = 0; n_clr_when_sat = 0;
        n_rst_with_en = 0; n_rst_when_sat = 0; n_hold = 0;
        verdict_done = 1'b0;
        rs = 32'h1BAD_5EED;

        nonce = 0;
        if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                    if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
                        if (!$value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce))
                            $display("WARNING: no nonce plusarg found");

        // ---- MAC-RESET: reset wins over an accumulate and over clr ----
        drive_edge(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_edge(1'b0, 1'b1, 1'b0, 8'h00, 8'h00);
        drive_edge(1'b0, 1'b0, 1'b0, 8'h12, 8'h34);

        // ---- MAC-ACC and MAC-HOLD ----
        drive_edge(1'b1, 1'b0, 1'b1, 8'h03, 8'h04);   // 12
        drive_edge(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);   // hold
        drive_edge(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);   // hold
        drive_edge(1'b1, 1'b0, 1'b1, 8'h80, 8'h01);   // +128 (unsigned)
        drive_edge(1'b1, 1'b0, 1'b1, 8'hFF, 8'h02);   // +510 (unsigned)
        drive_edge(1'b1, 1'b0, 1'b1, 8'h00, 8'hFF);   // +0
        drive_edge(1'b1, 1'b0, 1'b1, 8'hFF, 8'h00);   // +0
        drive_edge(1'b1, 1'b0, 1'b1, 8'h80, 8'h80);   // +16384

        // ---- MAC-CLEAR: clear wins over an accumulate ----
        drive_edge(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        drive_edge(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);   // 1
        drive_edge(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);   // plain clear

        // ---- MAC-SAT: land exactly on 0xFFFFFF, then overflow by one ----
        for (k = 0; k < 258; k = k + 1)
            drive_edge(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF); // 16776450
        drive_edge(1'b1, 1'b0, 1'b1, 8'h03, 8'hFF);   // exactly 0xFFFFFF, sat stays 0
        drive_edge(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);   // hold at max
        drive_edge(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);   // saturate

        // ---- MAC-STICKY ----
        drive_edge(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        drive_edge(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_edge(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);
        drive_edge(1'b1, 1'b0, 1'b1, 8'h00, 8'h07);
        drive_edge(1'b1, 1'b0, 1'b0, 8'hAA, 8'h55);

        // ---- clear while saturated, then flag stays cleared ----
        drive_edge(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        drive_edge(1'b1, 1'b0, 1'b1, 8'h02, 8'h03);   // 6, sat 0

        // ---- overshoot in a single step, then reset while saturated ----
        for (k = 0; k < 259; k = k + 1)
            drive_edge(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        drive_edge(1'b1, 1'b0, 1'b1, 8'h10, 8'h10);
        drive_edge(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);   // reset with en while saturated
        drive_edge(1'b1, 1'b0, 1'b1, 8'h05, 8'h05);   // 25, sat 0

        // ---- seeded random phase ----
        $display("random phase: %0d edges, xorshift32 seed 32'h1BAD5EED", RAND_EDGES);
        for (k = 0; k < RAND_EDGES; k = k + 1) begin
            rnd_next; ctl = rs;
            rnd_next; opd = rs;
            r_rst = (ctl[10:0] != 11'd0);        // low about 1 in 2048
            r_clr = (ctl[21:12] == 10'd0);       // high about 1 in 1024
            r_en  = (ctl[24:22] != 3'd0);        // high 7 in 8
            if (opd[0]) begin
                ra = {3'b111, opd[12:8]};
                rb = {3'b111, opd[20:16]};
            end else begin
                ra = opd[15:8];
                rb = opd[23:16];
            end
            if (opd[31:28] == 4'd0) ra = 8'd0;
            drive_edge(r_rst, r_clr, r_en, ra, rb);
        end

        // ---- corners must have been reached ----
        if (n_sat_set > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: saturation set"); end
        if (n_sticky > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: sticky flag held"); end
        if (n_exact_max > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: exact 0xFFFFFF without saturation"); end
        if (n_clr_with_en > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: clear with accumulate"); end
        if (n_clr_when_sat > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: clear while saturated"); end
        if (n_rst_with_en > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: reset with accumulate"); end
        if (n_rst_when_sat > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: reset while saturated"); end
        if (n_hold > 0) n_pass = n_pass + 1;
        else begin n_fail = n_fail + 1; $display("CORNER NOT REACHED: hold"); end

        $display("corners: sat_set=%0d sticky=%0d exact_max=%0d clr_with_en=%0d clr_when_sat=%0d rst_with_en=%0d rst_when_sat=%0d hold=%0d",
                 n_sat_set, n_sticky, n_exact_max, n_clr_with_en, n_clr_when_sat,
                 n_rst_with_en, n_rst_when_sat, n_hold);
        $display("edges driven: %0d", cycle);

        print_verdict;
        $finish;
    end

    // Watchdog: report a failure if the stimulus never completes.
    initial begin
        #5000000;
        if (!verdict_done) begin
            $display("TIMEOUT: stimulus did not complete");
            n_fail = n_fail + 1;
            print_verdict;
            $finish;
        end
    end
endmodule
=== END FILE ===
